    #         out = f"{name}{num}"
    #     return out

    def free_name(self):
        """discard the name in the namespace"""
        try:
            self._namespace.remove(self)
        except KeyError:
            print("not found in namespace")
        except AttributeError:
            print("this should not have happened.")

    @property
    def name(self):
        """access name attribute"""
        return self._name

    @property
    def size(self):
        """access size attribute"""
        return self._size

    @property
    def vtype(self):
        """access variable type"""
        return self._VAR_IDENTIFIER

    def __del__(self):
        self.free_name()

    def __init_subclass__(cls, prefix=None):
        if prefix is not None:
            cls._CLASS_BASE = prefix

    def expr_at_offset(self, offset):
        """expression at offset"""
        return f"{self._name}[{offset}]"

    def expr(self):
        """expression for the variable"""
        return f"{self._name}"

